import java.util.*;

final class Plot {
    record Cell(int col, int row) {}
    static char[][] canvas(int width, int height) {
        char[][] grid = new char[height][width];
        for (char[] row : grid)
            Arrays.fill(row, ' ');
        return grid;
    }
    static Cell map(Predicates.Point point, int width, int height) {
        return new Cell((int)((2 * point.x() * (width - 1) + 1000) / 2000),
                        height - 1 - (int)((2 * point.y() * (height - 1) + 1000) / 2000));
    }
    static Cell center(Predicates.Center point, int width, int height) {
        return new Cell((int)((2 * point.x() * (width - 1) + 1000 * point.d()) / (2000 * point.d())),
                        height - 1 -
                            (int)((2 * point.y() * (height - 1) + 1000 * point.d()) / (2000 * point.d())));
    }
    static void line(char[][] grid, Cell from, Cell to, char ch) {
        int x = from.col(), y = from.row(), dx = Math.abs(to.col() - x), dy = -Math.abs(to.row() - y),
            sx = x < to.col() ? 1 : -1, sy = y < to.row() ? 1 : -1, e = dx + dy;
        while (true) {
            grid[y][x] = ch;
            if (x == to.col() && y == to.row())
                break;
            int e2 = 2 * e;
            if (e2 >= dy) {
                e += dy;
                x += sx;
            }
            if (e2 <= dx) {
                e += dx;
                y += sy;
            }
        }
    }
    static List<String> frame(char[][] grid) {
        String border = "+"
                        + "-".repeat(grid[0].length) + "+";
        List<String> result = new ArrayList<>();
        result.add(border);
        for (char[] row : grid)
            result.add("|" + new String(row) + "|");
        result.add(border);
        return result;
    }
    static char[][] voronoi(List<Predicates.Point> points, int width, int height) {
        char[][] grid = canvas(width, height);
        int[][] owners = new int[height][width];
        for (int row = 0; row < height; row++)
            for (int col = 0; col < width; col++) {
                long best = Long.MAX_VALUE;
                int owner = 0;
                for (int site = 1; site < points.size(); site++) {
                    Predicates.Point p = points.get(site);
                    long x = (col * 1000 - p.x() * (width - 1)) * (height - 1),
                         y = ((height - 1 - row) * 1000 - p.y() * (height - 1)) * (width - 1),
                         delta = x * x + y * y;
                    if (delta < best) {
                        best = delta;
                        owner = site;
                    }
                }
                owners[row][col] = owner;
            }
        for (int row = 0; row < height; row++)
            for (int col = 0; col < width; col++)
                if (col + 1 < width && owners[row][col] != owners[row][col + 1] ||
                    row + 1 < height && owners[row][col] != owners[row + 1][col])
                    grid[row][col] = '#';
        for (int site = 1; site < points.size(); site++) {
            Cell cell = map(points.get(site), width, height);
            grid[cell.row()][cell.col()] = 'o';
        }
        return grid;
    }
}

final class Predicates {
    record Point(long x, long y) {}
    record Center(long x, long y, long d) {}
    static long orient(Point p, Point q, Point r) {
        return (q.x() - p.x()) * (r.y() - p.y()) - (q.y() - p.y()) * (r.x() - p.x());
    }
    static long d2(Point p, Point q) {
        long x = p.x() - q.x(), y = p.y() - q.y();
        return x * x + y * y;
    }
    static long dot(Point o, Point p, Point q) {
        return (p.x() - o.x()) * (q.x() - o.x()) + (p.y() - o.y()) * (q.y() - o.y());
    }
    static long incircle(Point a, Point b, Point c, Point d) {
        long ax = a.x() - d.x(), ay = a.y() - d.y(), bx = b.x() - d.x(), by = b.y() - d.y(),
             cx = c.x() - d.x(), cy = c.y() - d.y(), aa = ax * ax + ay * ay, bb = bx * bx + by * by,
             cc = cx * cx + cy * cy;
        return ax * (by * cc - bb * cy) - ay * (bx * cc - bb * cx) + aa * (bx * cy - by * cx);
    }
    static Center center(Point a, Point b, Point c) {
        long bx = b.x() - a.x(), by = b.y() - a.y(), cx = c.x() - a.x(), cy = c.y() - a.y(),
             bb = bx * bx + by * by, cc = cx * cx + cy * cy, d = 2 * (bx * cy - by * cx);
        return new Center(a.x() * d + cy * bb - by * cc, a.y() * d + bx * cc - cx * bb, d);
    }
    static long gcd(long a, long b) {
        a = Math.abs(a);
        b = Math.abs(b);
        while (b != 0) {
            long rest = a % b;
            a = b;
            b = rest;
        }
        return a;
    }
    static String fraction(long n, long d) {
        long g = gcd(n, d);
        n /= g;
        d /= g;
        return d == 1 ? Long.toString(n) : n + "/" + d;
    }
    static Point reduce(long x, long y) {
        long g = gcd(x, y);
        return new Point(x / g, y / g);
    }
}

import java.util.*;

final class Proximity {
    static final class Sets {
        int[] parent, size;
        int count;
        Sets(int n) {
            count = n;
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }
        int find(int i) {
            while (parent[i] != i) {
                parent[i] = parent[parent[i]];
                i = parent[i];
            }
            return i;
        }
        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b)
                return false;
            if (size[a] < size[b]) {
                int swap = a;
                a = b;
                b = swap;
            }
            parent[b] = a;
            size[a] += size[b];
            count--;
            return true;
        }
    }
    static int[] nearest(List<Predicates.Point> points, List<List<Integer>> neighbors) {
        int[] result = new int[points.size()];
        for (int s = 1; s < points.size(); s++) {
            int best = 0;
            long distance = Long.MAX_VALUE;
            for (int t : neighbors.get(s)) {
                long candidate = Predicates.d2(points.get(s), points.get(t));
                if (candidate < distance || candidate == distance && t < best) {
                    best = t;
                    distance = candidate;
                }
            }
            result[s] = best;
        }
        return result;
    }
    static List<List<Integer>> components(int[] nearest) {
        Sets sets = new Sets(nearest.length - 1);
        for (int s = 1; s < nearest.length; s++)
            sets.union(s, nearest[s]);
        Map<Integer, List<Integer>> groups = new HashMap<>();
        for (int s = 1; s < nearest.length; s++)
            groups.computeIfAbsent(sets.find(s), key -> new ArrayList<>()).add(s);
        List<List<Integer>> result = new ArrayList<>(groups.values());
        result.sort(Comparator.comparingInt(row -> row.get(0)));
        return result;
    }
    static List<Triangulation.Edge> mst(List<Predicates.Point> points, List<Triangulation.Edge> edges) {
        List<Triangulation.Edge> ordered = new ArrayList<>(edges);
        ordered.sort((a, b) -> {
            int comparison = Long.compare(Predicates.d2(points.get(a.a()), points.get(a.b())),
                                          Predicates.d2(points.get(b.a()), points.get(b.b())));
            return comparison != 0 ? comparison : a.compareTo(b);
        });
        Sets sets = new Sets(points.size() - 1);
        List<Triangulation.Edge> result = new ArrayList<>();
        for (Triangulation.Edge edge : ordered)
            if (sets.union(edge.a(), edge.b()))
                result.add(edge);
        return result;
    }
    static boolean gabriel(List<Predicates.Point> points, Triangulation.Edge edge,
                           Map<Triangulation.Edge, Integer> directed) {
        for (Triangulation.Edge e : List.of(edge, new Triangulation.Edge(edge.b(), edge.a()))) {
            Integer q = directed.get(e);
            if (q != null && Predicates.dot(points.get(q), points.get(edge.a()), points.get(edge.b())) <= 0)
                return false;
        }
        return true;
    }
    static boolean rng(List<Predicates.Point> points, Triangulation.Edge edge) {
        long length = Predicates.d2(points.get(edge.a()), points.get(edge.b()));
        for (int k = 1; k < points.size(); k++)
            if (Predicates.d2(points.get(edge.a()), points.get(k)) < length &&
                Predicates.d2(points.get(edge.b()), points.get(k)) < length)
                return false;
        return true;
    }
    record Route(List<Integer> sites, double length) {}
    static Route route(List<Predicates.Point> points, List<List<Integer>> neighbors, int start, int target) {
        List<Integer> path = new ArrayList<>();
        path.add(start);
        double length = 0;
        int current = start;
        while (current != target) {
            int best = 0;
            long distance = Long.MAX_VALUE;
            for (int t : neighbors.get(current)) {
                long candidate = Predicates.d2(points.get(t), points.get(target));
                if (candidate < distance || candidate == distance && t < best) {
                    best = t;
                    distance = candidate;
                }
            }
            length += Math.sqrt(Predicates.d2(points.get(current), points.get(best)));
            path.add(best);
            current = best;
        }
        return new Route(path, length);
    }
    record Paths(double[] distance, int[] previous) {
        List<Integer> path(int target) {
            List<Integer> result = new ArrayList<>();
            for (int current = target; current != 0; current = previous[current])
                result.add(current);
            Collections.reverse(result);
            return result;
        }
    }
    static Paths dijkstra(List<Predicates.Point> points, List<List<Integer>> neighbors, int start) {
        int n = points.size() - 1;
        double[] distance = new double[n + 1];
        Arrays.fill(distance, Double.POSITIVE_INFINITY);
        int[] previous = new int[n + 1];
        boolean[] done = new boolean[n + 1];
        distance[start] = 0;
        for (int step = 0; step < n; step++) {
            int site = 0;
            for (int s = 1; s <= n; s++)
                if (!done[s] && (site == 0 || distance[s] < distance[site]))
                    site = s;
            done[site] = true;
            for (int t : neighbors.get(site)) {
                double candidate = distance[site] + Math.sqrt(Predicates.d2(points.get(site), points.get(t)));
                if (candidate < distance[t]) {
                    distance[t] = candidate;
                    previous[t] = site;
                }
            }
        }
        return new Paths(distance, previous);
    }
}

import java.util.*;

final class Triangulation {
    record Edge(int a, int b) implements Comparable<Edge> {
        public int compareTo(Edge e) {
            int c = Integer.compare(a, e.a());
            return c != 0 ? c : Integer.compare(b, e.b());
        }
    }
    record Triangle(int a, int b, int c) implements Comparable<Triangle> {
        public int compareTo(Triangle t) {
            int result = Integer.compare(a, t.a());
            if (result == 0)
                result = Integer.compare(b, t.b());
            return result != 0 ? result : Integer.compare(c, t.c());
        }
        int[] sites() {
            return new int[] {a, b, c};
        }
    }
    static Edge key(int a, int b) {
        return new Edge(Math.min(a, b), Math.max(a, b));
    }
    static Triangle canonical(int a, int b, int c) {
        return a < b && a < c ? new Triangle(a, b, c) : b < c ? new Triangle(b, c, a) : new Triangle(c, a, b);
    }
    record Insertion(String kind, Triangle containing, int visible, int flips, int triangles, int hull) {}
    static final class Model {
        List<Predicates.Point> points;
        Map<Edge, Integer> directed = new HashMap<>();
        Triangle initial;
        Model(List<Predicates.Point> points) {
            this.points = points;
            initial = Predicates.orient(points.get(1), points.get(2), points.get(3)) > 0
                          ? new Triangle(1, 2, 3)
                          : new Triangle(1, 3, 2);
            add(initial.a(), initial.b(), initial.c());
        }
        void add(int a, int b, int c) {
            directed.put(new Edge(a, b), c);
            directed.put(new Edge(b, c), a);
            directed.put(new Edge(c, a), b);
        }
        void remove(int a, int b, int c) {
            directed.remove(new Edge(a, b));
            directed.remove(new Edge(b, c));
            directed.remove(new Edge(c, a));
        }
        List<Triangle> triangles() {
            SortedSet<Triangle> result = new TreeSet<>();
            for (Map.Entry<Edge, Integer> entry : directed.entrySet())
                result.add(canonical(entry.getKey().a(), entry.getKey().b(), entry.getValue()));
            return new ArrayList<>(result);
        }
        List<Edge> hullEdges() {
            List<Edge> result = new ArrayList<>();
            for (Edge e : directed.keySet())
                if (!directed.containsKey(new Edge(e.b(), e.a())))
                    result.add(e);
            Collections.sort(result);
            return result;
        }
        Insertion insert(int site) {
            Triangle containing = null;
            for (Triangle t : triangles())
                if (Predicates.orient(points.get(t.a()), points.get(t.b()), points.get(site)) > 0 &&
                    Predicates.orient(points.get(t.b()), points.get(t.c()), points.get(site)) > 0 &&
                    Predicates.orient(points.get(t.c()), points.get(t.a()), points.get(site)) > 0) {
                    containing = t;
                    break;
                }
            SortedSet<Edge> check = new TreeSet<>();
            int visible = 0;
            if (containing != null) {
                int a = containing.a(), b = containing.b(), c = containing.c();
                remove(a, b, c);
                check.add(new Edge(a, b));
                check.add(new Edge(b, c));
                check.add(new Edge(c, a));
            } else {
                for (Edge e : hullEdges())
                    if (Predicates.orient(points.get(e.a()), points.get(e.b()), points.get(site)) < 0)
                        check.add(new Edge(e.b(), e.a()));
                visible = check.size();
            }
            for (Edge e : check)
                add(e.a(), e.b(), site);
            int flips = 0;
            while (!check.isEmpty()) {
                Edge edge = check.first();
                check.remove(edge);
                int a = edge.a(), b = edge.b();
                Integer q = directed.get(new Edge(b, a));
                if (q != null &&
                    Predicates.incircle(points.get(a), points.get(b), points.get(site), points.get(q)) > 0) {
                    remove(a, b, site);
                    remove(b, a, q);
                    add(a, q, site);
                    add(q, b, site);
                    check.add(new Edge(a, q));
                    check.add(new Edge(q, b));
                    flips++;
                }
            }
            return new Insertion(containing == null ? "outside" : "inside", containing, visible, flips,
                                 directed.size() / 3, hullEdges().size());
        }
    }
    record Walk(List<Integer> path, Edge outside) {}
    static Walk walk(Predicates.Point query, List<Predicates.Point> points, List<Triangle> triangles,
                     Map<Edge, Integer> directed) {
        List<Integer> path = new ArrayList<>();
        path.add(1);
        while (true) {
            Triangle t = triangles.get(path.getLast() - 1);
            boolean moved = false;
            for (Edge e : List.of(new Edge(t.a(), t.b()), new Edge(t.b(), t.c()), new Edge(t.c(), t.a())))
                if (Predicates.orient(points.get(e.a()), points.get(e.b()), query) < 0) {
                    Integer next = directed.get(new Edge(e.b(), e.a()));
                    if (next == null)
                        return new Walk(path, key(e.a(), e.b()));
                    path.add(next);
                    moved = true;
                    break;
                }
            if (!moved)
                return new Walk(path, null);
        }
    }
}

import java.util.*;

final class Voronoi {
    record Vertex(Predicates.Center center, double r2, String position) {}
    record RealPoint(double x, double y) {}
    static double radius2(Predicates.Point a, Predicates.Point b, Predicates.Point c) {
        long area = Predicates.orient(a, b, c);
        return (((double)Predicates.d2(a, b) * Predicates.d2(b, c)) * Predicates.d2(c, a)) /
            ((4.0 * area) * area);
    }
    static String position(Predicates.Center v, List<Integer> hull, List<Predicates.Point> points) {
        boolean on = false;
        for (int i = 0; i < hull.size(); i++) {
            Predicates.Point a = points.get(hull.get(i)), b = points.get(hull.get((i + 1) % hull.size()));
            long sigma =
                (b.x() - a.x()) * (v.y() - a.y() * v.d()) - (b.y() - a.y()) * (v.x() - a.x() * v.d());
            if (sigma < 0)
                return "outside";
            if (sigma == 0)
                on = true;
        }
        return on ? "on" : "inside";
    }
    static Predicates.Point outward(Predicates.Point a, Predicates.Point b) {
        return Predicates.reduce(b.y() - a.y(), a.x() - b.x());
    }
    static List<Integer> neighbors(int site, List<Integer> adjacent,
                                   Map<Triangulation.Edge, Integer> directed, Integer next) {
        int start = next == null ? Collections.min(adjacent) : next;
        List<Integer> result = new ArrayList<>();
        int current = start;
        while (true) {
            result.add(current);
            Integer following = directed.get(new Triangulation.Edge(site, current));
            if (following == null || following == start)
                break;
            current = following;
        }
        return result;
    }
    static double area(int site, List<Integer> vertexIds, List<Vertex> vertices,
                       List<Predicates.Point> points) {
        Predicates.Point origin = points.get(site);
        double sum = 0;
        for (int i = 0; i < vertexIds.size(); i++) {
            Predicates.Center a = vertices.get(vertexIds.get(i) - 1).center(),
                              b = vertices.get(vertexIds.get((i + 1) % vertexIds.size()) - 1).center();
            double u = (double)a.x() / a.d() - origin.x(), w = (double)a.y() / a.d() - origin.y(),
                   un = (double)b.x() / b.d() - origin.x(), wn = (double)b.y() / b.d() - origin.y();
            sum += u * wn - un * w;
        }
        return sum / 2;
    }
    static double clipped(int site, List<Integer> neighbors, List<Predicates.Point> points) {
        List<RealPoint> polygon = new ArrayList<>(List.of(new RealPoint(0, 0), new RealPoint(1000, 0),
                                                          new RealPoint(1000, 1000), new RealPoint(0, 1000)));
        Predicates.Point s = points.get(site);
        for (int neighbor : neighbors) {
            Predicates.Point t = points.get(neighbor);
            long c1 = 2 * (t.x() - s.x()), c2 = 2 * (t.y() - s.y()),
                 c3 = t.x() * t.x() + t.y() * t.y() - s.x() * s.x() - s.y() * s.y();
            List<RealPoint> next = new ArrayList<>();
            for (int i = 0; i < polygon.size(); i++) {
                RealPoint a = polygon.get(i), b = polygon.get((i + 1) % polygon.size());
                double fa = c1 * a.x() + c2 * a.y() - c3, fb = c1 * b.x() + c2 * b.y() - c3;
                if (fa <= 0)
                    next.add(a);
                if (fa < 0 && fb > 0 || fb < 0 && fa > 0) {
                    double lambda = fa / (fa - fb);
                    next.add(
                        new RealPoint(a.x() + (b.x() - a.x()) * lambda, a.y() + (b.y() - a.y()) * lambda));
                }
            }
            polygon = next;
        }
        double sum = 0;
        for (int i = 0; i < polygon.size(); i++) {
            RealPoint a = polygon.get(i), b = polygon.get((i + 1) % polygon.size());
            sum += a.x() * b.y() - b.x() * a.y();
        }
        return sum / 2;
    }
}
